import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import SupplierLedger from '../../../src/pages/SupplierLedger.jsx';import {supabase} from '../../../src/lib/supabase.js';import '../../../src/index.css';import '../../../src/styles/move-design.css';
const storage=[{id:1,kind:'defect',item_name:'비코닉 RW 모듈 메모리 기억안되는 증상',spec:'RW모듈',qty:1,unit:'개',note:'JSR 본사 선불 발송',resolved:false}];let returns=[];window.savedReturns=returns;
supabase.getSupplierLedger=async()=>storage;supabase.getDefectReturns=async()=>returns;supabase.addDefectReturn=async p=>{returns=[...returns,{...p,id:77}];window.savedReturns=returns;return [p]};supabase.updateDefectReturn=async(id,p)=>{returns=returns.map(r=>r.id===id?{...r,...p}:r);window.savedReturns=returns;return [p]};
